loginUrl:
var QQ_GROUP = "1097919737";
var MAKER_QQ = "1820480783";
function siteBase(){ return "https://www.ishuku.com"; }
function isAlive(u){
  try{
    var t = String(java.ajax(u) || "");
    return t.length > 200;
  }catch(e){ return false; }
}
function login(){
  try{ java.upLoginData(); }catch(e){}
  java.toast("设置已保存");
}
function checkSite(){
  var ok = isAlive(siteBase());
  java.longToast("🌐 当前站点：" + siteBase() + (ok ? "（可用）" : "（不可用，可能被墙/换域名）"));
}
function checkSearch(){
  try{
    var html = String(java.ajax("https://www.rrssk.com/005E.html") || "");
    var mt = html.match(/name="_t" value="([a-f0-9]+)"/);
    var mv = html.match(/action=signJs&v=([^"']+)/);
    if(!mt || !mv){ java.longToast("❌ 搜索服务异常（无法获取搜索令牌）"); return; }
    java.longToast("✅ 当前搜索正常（爱书库 / 005E）");
  }catch(e){ java.longToast("❌ 搜索服务异常：" + e); }
}
function joinQQGroup(){
  var u = "mqqapi://card/show_pslcard?src_type=internal&version=1&card_type=group&uin=" + QQ_GROUP;
  try{
    java.openUrl(u);
    java.toast("已尝试打开QQ，若未跳转请手动搜索群号 " + QQ_GROUP);
  }catch(e){ java.longToast("请手动在QQ中搜索群号 " + QQ_GROUP); }
}
function contactMaker(){
  var u = "mqqapi://card/show_pslcard?src_type=internal&version=1&card_type=friend&uin=" + MAKER_QQ;
  try{
    java.openUrl(u);
    java.toast("已尝试打开QQ，若未跳转请手动添加 " + MAKER_QQ);
  }catch(e){ java.longToast("请手动在QQ中搜索 " + MAKER_QQ); }
}

